from taf.gnb.oam.coam.vdu import vdu as du_admin

from taf.rfrl.l3_call.cell.cell import Cell
from taf.rfrl.l3_call.logger.l3_call_logger import log_operation


class CloudCell(Cell):
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"

    def __init__(self, cell_distname, vdu_aliases, shared_spectrum):
        super(CloudCell, self).__init__(cell_distname, shared_spectrum)
        self._admin_du = du_admin()
        self.vdu_alias = self._get_vdu_alias_for_this_cell(vdu_aliases=vdu_aliases)

    def get_spectrum(self):
        """
        Calculates lower and upper limit of cell spectrum

        :return: list where first element is lower limit of frequency
        and second element is upper limit of frequency
        :rtype: list(float)
        """
        channel_bandwidth, carrier_frequency = self._get_carrier_frequency_and_channel_bandwidth()

        lower_frequency = carrier_frequency - 0.5 * channel_bandwidth
        upper_frequency = carrier_frequency + 0.5 * channel_bandwidth

        return [lower_frequency, upper_frequency]

    def _get_carrier_frequency_and_channel_bandwidth(self):
        nrarfcn = self._get_nrarfcn()
        carrier_frequency = self._calculate_carrier_frequency(nrarfcn=nrarfcn)
        channel_bandwidth = self._get_channel_bandwidth()

        return float(channel_bandwidth.replace("MHz", "")), int(carrier_frequency)

    def _get_vdu_alias_for_this_cell(self, vdu_aliases):
        for vdu_alias in vdu_aliases.values():
            for cell in self._admin_du.get_vdu_cells_status(vdu_connection=vdu_alias):
                if cell["dist_names"]["config"] == self.distname:
                    return vdu_alias

    def _get_nrarfcn(self):
        return self._admin_du.search_parameter_of_current_plan(mo_dn=self.distname, para_name="nrarfcn",
                                                               vdu_connection=self.vdu_alias)

    def _get_cell_technology(self):
        return self._admin_du.search_parameter_of_current_plan(mo_dn=self.distname, para_name="cellTechnology",
                                                               vdu_connection=self.vdu_alias)

    def _get_channel_bandwidth(self):
        return self._admin_du.search_parameter_of_current_plan(mo_dn=self.distname, para_name="chBw",
                                                               vdu_connection=self.vdu_alias)

    def _block_cell(self):
        log_operation("Blocking cell {}".format(self.distname))
        self._admin_du.block_cell(cell_id=self._configuration_id, timeout=60,
                                  vdu_connection=self.vdu_alias)

    def _unblock_cell(self):
        log_operation("Unblocking cell {}".format(self.distname))
        self._admin_du.unblock_cell(cell_id=self._configuration_id, timeout=60,
                                    vdu_connection=self.vdu_alias)

    def _get_blocking_state(self):
        for cell_info in self._admin_du.get_vdu_cells_status(vdu_connection=self.vdu_alias):
            if cell_info["dist_names"]["config"] == self.distname:
                return cell_info.get("blocking_state")

    def _is_cell_blocked(self):
        return self._get_blocking_state() == "Blocked"

    def _calculate_carrier_frequency(self, nrarfcn):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, "_calculate_carrier_frequency"))
